mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  p.y *= 1.6;
  p = rot(-0.4) * p;
  float r = length(p);
  float a = atan(p.y, p.x);
  float spiral = sin(a * 2.0 - log(r + 0.01) * 3.5 - time * 1.5);
  float arm = smoothstep(0.2, 0.9, spiral) * smoothstep(1.5, 0.2, r);
  float core = 0.04 / (0.02 + r * r * 2.5);
  vec3 col = vec3(0.01, 0.02, 0.04);
  col += arm * vec3(0.4, 0.7, 1.2) * 1.2;
  col += core * vec3(1.3, 0.9, 0.4) * (1.0 + 0.4 * bass);
  ret = col;
}
